"32x32": "http://localhost:8080/jira/secure/useravatar?size=medium&amp;ownerId=fred",
"48x48": "http://localhost:8080/jira/secure/useravatar?size=large&amp;ownerId=fred"
},
"displayName": "Fred F. User",
"active": true,
"timeZone": "Australia/Sydney",
"groups": {
